CREATE TABLE schema_version_v9(version INTEGER PRIMARY KEY CHECK(version IN(1,2,3,4,5,6,7,8,9)),backend TEXT NOT NULL CHECK(backend='postgres'),checksum TEXT NOT NULL);
INSERT INTO schema_version_v9 SELECT * FROM schema_version;
DROP TABLE schema_version;
ALTER TABLE schema_version_v9 RENAME TO schema_version;
CREATE TABLE interview_policy_version(org_id TEXT NOT NULL,employee_id TEXT NOT NULL,revision BIGINT NOT NULL CHECK(revision>0),cadence_unit TEXT NOT NULL CHECK(cadence_unit IN('day','week','month')),cadence_count INTEGER NOT NULL CHECK(cadence_count BETWEEN 1 AND 365),anchor_date DATE NOT NULL,timezone TEXT NOT NULL CHECK(length(timezone) BETWEEN 1 AND 128),due_offset_days INTEGER NOT NULL CHECK(due_offset_days BETWEEN 0 AND 365),local_due_time TEXT NOT NULL CHECK(local_due_time~'^([01][0-9]|2[0-3]):[0-5][0-9]$'),window_through DATE NOT NULL CHECK(window_through>anchor_date),pause_json TEXT NOT NULL CHECK(jsonb_typeof(pause_json::jsonb)='array'),purpose TEXT NOT NULL CHECK(purpose='interview_followup'),ai_mode TEXT NOT NULL CHECK(ai_mode IN('disabled','manual_approved','periodic_structured_v1')),required_fields_json TEXT NOT NULL CHECK(jsonb_typeof(required_fields_json::jsonb)='array'),updated_by TEXT NOT NULL,updated_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(org_id,employee_id,revision),FOREIGN KEY(org_id,employee_id) REFERENCES employee(org_id,id),FOREIGN KEY(org_id,updated_by) REFERENCES subject(org_id,id));
CREATE TABLE interview_policy(org_id TEXT NOT NULL,employee_id TEXT NOT NULL,revision BIGINT NOT NULL CHECK(revision>0),cadence_unit TEXT NOT NULL CHECK(cadence_unit IN('day','week','month')),cadence_count INTEGER NOT NULL CHECK(cadence_count BETWEEN 1 AND 365),anchor_date DATE NOT NULL,timezone TEXT NOT NULL CHECK(length(timezone) BETWEEN 1 AND 128),due_offset_days INTEGER NOT NULL CHECK(due_offset_days BETWEEN 0 AND 365),local_due_time TEXT NOT NULL CHECK(local_due_time~'^([01][0-9]|2[0-3]):[0-5][0-9]$'),window_through DATE NOT NULL CHECK(window_through>anchor_date),pause_json TEXT NOT NULL CHECK(jsonb_typeof(pause_json::jsonb)='array'),purpose TEXT NOT NULL CHECK(purpose='interview_followup'),ai_mode TEXT NOT NULL CHECK(ai_mode IN('disabled','manual_approved','periodic_structured_v1')),required_fields_json TEXT NOT NULL CHECK(jsonb_typeof(required_fields_json::jsonb)='array'),updated_by TEXT NOT NULL,updated_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(org_id,employee_id),FOREIGN KEY(org_id,employee_id,revision) REFERENCES interview_policy_version(org_id,employee_id,revision),FOREIGN KEY(org_id,updated_by) REFERENCES subject(org_id,id));
CREATE TABLE followup_window(org_id TEXT NOT NULL,employee_id TEXT NOT NULL,id TEXT NOT NULL,policy_revision BIGINT NOT NULL CHECK(policy_revision>0),local_start DATE NOT NULL,local_end DATE NOT NULL CHECK(local_end>local_start),start_at TIMESTAMPTZ NOT NULL,end_at TIMESTAMPTZ NOT NULL CHECK(end_at>start_at),due_at TIMESTAMPTZ NOT NULL,paused BOOLEAN NOT NULL,automation_state TEXT NOT NULL CHECK(automation_state IN('disabled','awaiting_manual_input','blocked','ready')),block_reason TEXT CHECK(block_reason IS NULL OR block_reason IN('automation_not_enabled','policy_expired','authorization_unavailable','provider_not_approved')),last_scanned_at TIMESTAMPTZ,PRIMARY KEY(org_id,id),UNIQUE(org_id,employee_id,policy_revision,local_start),FOREIGN KEY(org_id,employee_id,policy_revision) REFERENCES interview_policy_version(org_id,employee_id,revision));
CREATE TABLE assessment_command_receipt(org_id TEXT NOT NULL,subject_id TEXT NOT NULL,operation TEXT NOT NULL CHECK(operation='OP-AI-01'),key TEXT NOT NULL,digest BYTEA NOT NULL CHECK(octet_length(digest)=32),employee_id TEXT NOT NULL,result_revision BIGINT NOT NULL CHECK(result_revision>0),recorded_at TIMESTAMPTZ NOT NULL,PRIMARY KEY(org_id,subject_id,operation,key),FOREIGN KEY(org_id,subject_id) REFERENCES subject(org_id,id),FOREIGN KEY(org_id,employee_id,result_revision) REFERENCES interview_policy_version(org_id,employee_id,revision));
ALTER TABLE capability_assignment DROP CONSTRAINT capability_assignment_capability_check;
ALTER TABLE capability_assignment ADD CONSTRAINT capability_assignment_capability_check CHECK(capability IN('organization.read','organization.write','pii.read','pii.write','access_grant.manage','interview.read','interview.write','interview_policy.manage','note.read','note.write','note.publish','action.read','action.write','sensitive.export','compensation.read','compensation.propose','compensation.approve','bonus.target.manage','bonus.propose','bonus.approve','bonus.payment.record','compensation.extension.manage'));
ALTER TABLE delegation_authority DROP CONSTRAINT delegation_authority_capability_check;
ALTER TABLE delegation_authority ADD CONSTRAINT delegation_authority_capability_check CHECK(capability IN('organization.read','organization.write','pii.read','pii.write','interview.read','interview.write','interview_policy.manage','note.read','note.write','note.publish','action.read','action.write','sensitive.export','compensation.read','compensation.propose','compensation.approve','bonus.target.manage','bonus.propose','bonus.approve','bonus.payment.record','compensation.extension.manage'));
ALTER TABLE access_grant DROP CONSTRAINT access_grant_capability_check;
ALTER TABLE access_grant ADD CONSTRAINT access_grant_capability_check CHECK(capability IN('organization.read','organization.write','pii.read','pii.write','access_grant.manage','interview.read','interview.write','interview_policy.manage','note.read','note.write','note.publish','action.read','action.write','sensitive.export','compensation.read','compensation.propose','compensation.approve','bonus.target.manage','bonus.propose','bonus.approve','bonus.payment.record','compensation.extension.manage'));
ALTER TABLE delegation_authority DROP CONSTRAINT delegation_authority_category_check;
ALTER TABLE delegation_authority ADD CONSTRAINT delegation_authority_category_check CHECK((((category='metadata' AND capability IN('organization.read','organization.write') AND purpose='organization_management') OR (category='pii' AND capability IN('pii.read','pii.write') AND purpose='organization_management') OR (category='audit' AND capability='access_grant.manage' AND purpose='security_administration') OR (purpose='interview_followup' AND ((category='metadata' AND capability IN('interview.read','interview.write','interview_policy.manage','sensitive.export')) OR (category IN('shared','manager_private','hr_confidential') AND capability IN('note.read','note.write','note.publish','sensitive.export')) OR (category='shared' AND capability IN('action.read','action.write'))))) OR (category='financial' AND purpose='compensation_management' AND capability IN('compensation.read','compensation.propose','compensation.approve','bonus.target.manage','bonus.propose','bonus.approve','bonus.payment.record','compensation.extension.manage','sensitive.export'))) AND capability<>'access_grant.manage');
ALTER TABLE access_grant DROP CONSTRAINT access_grant_category_check;
ALTER TABLE access_grant ADD CONSTRAINT access_grant_category_check CHECK((((category='metadata' AND capability IN('organization.read','organization.write') AND purpose='organization_management') OR (category='pii' AND capability IN('pii.read','pii.write') AND purpose='organization_management') OR (category='audit' AND capability='access_grant.manage' AND purpose='security_administration') OR (purpose='interview_followup' AND ((category='metadata' AND capability IN('interview.read','interview.write','interview_policy.manage','sensitive.export')) OR (category IN('shared','manager_private','hr_confidential') AND capability IN('note.read','note.write','note.publish','sensitive.export')) OR (category='shared' AND capability IN('action.read','action.write'))))) OR (category='financial' AND purpose='compensation_management' AND capability IN('compensation.read','compensation.propose','compensation.approve','bonus.target.manage','bonus.propose','bonus.approve','bonus.payment.record','compensation.extension.manage','sensitive.export'))));
ALTER TABLE audit_event DROP CONSTRAINT audit_event_operation_check;
ALTER TABLE audit_event ADD CONSTRAINT audit_event_operation_check CHECK(operation IN('OP-ORG-01','OP-ORG-02','OP-ORG-03','OP-ORG-04','OP-ORG-05','OP-ORG-07','OP-ORG-06','OP-ORG-08','OP-SEC-01','OP-SEC-02','OP-SEC-03','OP-SEC-06','AUTH-LOGIN','AUTH-STEP-UP','AUTH-LOGOUT','AUTH-BIND','AUTH-UNBIND','OP-INT-01','OP-INT-02','OP-INT-03','OP-INT-04','OP-INT-05','OP-INT-06','OP-INT-07','OP-INT-08','OP-SEC-05','OP-COMP-01','OP-COMP-02','OP-COMP-03','OP-COMP-04','OP-COMP-05','OP-BONUS-01','OP-BONUS-02','OP-BONUS-03','OP-BONUS-04','OP-BONUS-05','OP-BONUS-06','OP-BONUS-07','OP-BONUS-08','OP-AI-01','OP-AI-02'));
ALTER TABLE oidc_transaction DROP CONSTRAINT oidc_transaction_action_check;
ALTER TABLE oidc_transaction ADD CONSTRAINT oidc_transaction_action_check CHECK(action IN('','pii.write','access_grant.manage','note.publish','sensitive.export','compensation.read','compensation.propose','compensation.approve','bonus.target.manage','bonus.propose','bonus.approve','bonus.payment.record','compensation.extension.manage','interview_policy.manage'));
ALTER TABLE oidc_transaction DROP CONSTRAINT oidc_transaction_check2;
ALTER TABLE oidc_transaction ADD CONSTRAINT oidc_transaction_check2 CHECK((mode='login' AND action='' AND expected_identity IS NULL) OR (mode='step_up' AND action IN('pii.write','access_grant.manage','note.publish','sensitive.export','compensation.read','compensation.propose','compensation.approve','bonus.target.manage','bonus.propose','bonus.approve','bonus.payment.record','compensation.extension.manage','interview_policy.manage') AND previous_hash IS NOT NULL AND expected_identity IS NOT NULL));
CREATE INDEX followup_window_due ON followup_window(org_id,due_at,id);
CREATE INDEX followup_window_employee ON followup_window(org_id,employee_id,policy_revision,start_at,id);
CREATE FUNCTION assessment_fact_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable assessment fact' USING ERRCODE='23514'; END $$;
CREATE FUNCTION followup_window_owner_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.org_id IS DISTINCT FROM OLD.org_id OR NEW.employee_id IS DISTINCT FROM OLD.employee_id OR NEW.id IS DISTINCT FROM OLD.id OR NEW.policy_revision IS DISTINCT FROM OLD.policy_revision OR NEW.local_start IS DISTINCT FROM OLD.local_start OR NEW.local_end IS DISTINCT FROM OLD.local_end OR NEW.start_at IS DISTINCT FROM OLD.start_at OR NEW.end_at IS DISTINCT FROM OLD.end_at OR NEW.due_at IS DISTINCT FROM OLD.due_at OR NEW.paused IS DISTINCT FROM OLD.paused THEN RAISE EXCEPTION 'immutable assessment owner' USING ERRCODE='23514'; END IF; RETURN NEW; END $$;
CREATE TRIGGER interview_policy_version_immutable BEFORE UPDATE OR DELETE ON interview_policy_version FOR EACH ROW EXECUTE FUNCTION assessment_fact_immutable();
CREATE TRIGGER followup_window_owner_immutable BEFORE UPDATE ON followup_window FOR EACH ROW EXECUTE FUNCTION followup_window_owner_immutable();
CREATE TRIGGER followup_window_delete_immutable BEFORE DELETE ON followup_window FOR EACH ROW EXECUTE FUNCTION assessment_fact_immutable();
CREATE TRIGGER assessment_receipt_immutable BEFORE UPDATE OR DELETE ON assessment_command_receipt FOR EACH ROW EXECUTE FUNCTION assessment_fact_immutable();
